input.old_string:
OutlinedButton(onClick = {
    viewModel.shuffleTracks(state.tracks)
    navController.navigate(Screen.NowPlaying.route)
}) {
    Icon(Icons.Default.Shuffle, null)
    Spacer(Modifier.width(4.dp))
    Text("Shuffle")
}

} else {
    items(state.albums) { album ->
        AlbumCard(
            album = album,
            onClick = { navController.navigate(Screen.AlbumDetail.createRoute(album.id)) },
            modifier = Modifier.fillMaxWidth(),
        )
        HorizontalDivider()
    }
}

input.new_string:
} else {
    items(state.albums) { album ->
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clickable { navController.navigate(Screen.AlbumDetail.createRoute(album.id)) }
                .padding(horizontal = 16.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Surface(
                shape = MaterialTheme.shapes.small,
                tonalElevation = 2.dp,
                modifier = Modifier.size(56.dp).clip(MaterialTheme.shapes.small),
            ) {
                AsyncImage(
                    model = album.albumArtUri,
                    contentDescription = album.name,
                    contentScale = ContentScale.Crop,
                    modifier = Modifier.fillMaxSize(),
                )
            }
            Spacer(Modifier.width(12.dp))
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = album.name,
                    style = MaterialTheme.typography.titleMedium,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = if (album.year > 0) "${album.artist} · ${album.year}" else album.artist,
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        }
        HorizontalDivider()
    }
}
